-- 20261105 rof2b port: mesa-centaur - Mesa Centaur's Troubles chain + corruption state (4 quests).
-- Source: github.com/nightstalker6669/EQEmu branch rof2-achievements,
--   extensions/rof2/achievements/content/mesa-centaur (GPL-3.0), ported 2026-11-05.
-- Forward SQL files concatenated verbatim in install order; fail-closed
-- guards and session variables preserved. Reviewed-flag acceptance block
-- added here (upstream reconstruction defaults documented in the package's
-- provenance/ directory; see docs/rof2-zone-quests-attribution.md).
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;

-- ---- mesa-centaur/sql/010-centaur-chain.sql ----
SET NAMES utf8mb4;
DELIMITER //
BEGIN NOT ATOMIC
 DECLARE held INT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  ROLLBACK;
  IF held=1 THEN DO RELEASE_LOCK('rof2.mesa.centaur.3040461'); END IF;
  RESIGNAL;
 END;
 SELECT GET_LOCK('rof2.mesa.centaur.3040461',0) INTO held;
 IF held<>1 OR held IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Centaur package is locked'; END IF;
 START TRANSACTION;

IF (SELECT COUNT(*) FROM `tasks` WHERE id BETWEEN 3040461 AND 3040464 AND title IN ('Centaur Troubles - Prove Yourself','Centaur Troubles - Reduce the Thug Menace','Centaur Troubles - Research the Centaur Malady','Centaur Troubles - Cure the Malady')) <> 4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Centaur preimage conflict: tasks'; END IF;
IF (SELECT COUNT(*) FROM `tasks` WHERE id BETWEEN 3040461 AND 3040464) <> 4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Centaur preimage conflict: task_activities'; END IF;
IF (SELECT COUNT(*) FROM `achievement_criteria` WHERE achievement_id=500041000 AND component_type=1 AND component_id BETWEEN 50171 AND 50174) <> 4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Centaur preimage conflict: achievement_criteria'; END IF;
IF (SELECT COUNT(*) FROM `reward_sets` WHERE reward_set_id=3040464) <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Centaur preimage conflict: reward_sets'; END IF;
IF (SELECT COUNT(*) FROM `reward_sources` WHERE (source_type=2 AND source_id=3040464) OR reward_set_id=3040464) <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Centaur preimage conflict: reward_sources'; END IF;
IF (SELECT COUNT(*) FROM `reward_options` WHERE reward_set_id=3040464) <> 3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Centaur preimage conflict: reward_options'; END IF;
IF (SELECT COUNT(*) FROM `reward_option_entries` WHERE reward_set_id=3040464 OR reward_id BETWEEN 304046401 AND 304046403) <> 3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Centaur preimage conflict: reward_option_entries'; END IF;
IF (SELECT COUNT(*) FROM `rewards` WHERE reward_id BETWEEN 304046401 AND 304046403) <> 3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Centaur preimage conflict: rewards'; END IF;
IF (SELECT COUNT(*) FROM `reward_source_entries` WHERE reward_id BETWEEN 304046401 AND 304046403) <> 0 OR EXISTS(SELECT 1 FROM `reward_source_entries` WHERE (reward_id BETWEEN 304046401 AND 304046403) AND NOT(FALSE)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Centaur preimage conflict: reward_source_entries'; END IF;
IF (SELECT COUNT(*) FROM `achievements` WHERE id=500041000) <> 1 OR EXISTS(SELECT 1 FROM `achievements` WHERE (id=500041000) AND NOT((`id` <=> 500041000 AND `name` <=> CONVERT(0x43656e7461757227732054726f75626c657320284d6573612035302b29 USING utf8mb4) AND `description` <=> CONVERT(0x576f726b20776974682053636f7574204d61647520746f206761696e206661766f722077697468204b6c617373722c207468656e206173736973742068696d20696e20637572696e672074686520696c6c7320626566616c6c696e67207468652063656e74617572733a USING utf8mb4) AND `icon_id` <=> 1907 AND `points` <=> 4 AND `has_reward` <=> 1 AND `client_flag` <=> 0 AND `version` <=> 0 AND `reset_on_version_change` <=> 1 AND (`enabled` <=> 0 OR `enabled` <=> 1)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Centaur preimage conflict: achievements'; END IF;
IF (SELECT COUNT(*) FROM `achievement_components` WHERE achievement_id=500041000 AND component_id<>7014) <> 6 OR EXISTS(SELECT 1 FROM `achievement_components` WHERE (achievement_id=500041000 AND component_id<>7014) AND NOT((`achievement_id` <=> 500041000 AND `component_type` <=> 1 AND `sequence` <=> 1 AND `component_id` <=> 50171 AND `name` <=> CONVERT(0x53636f7574204d616475202d2050726f766520596f757273656c66 USING utf8mb4) AND `description` <=> '') OR (`achievement_id` <=> 500041000 AND `component_type` <=> 1 AND `sequence` <=> 2 AND `component_id` <=> 50172 AND `name` <=> CONVERT(0x4b6c61737372202d20526564756365207468652054687567204d656e616365 USING utf8mb4) AND `description` <=> '') OR (`achievement_id` <=> 500041000 AND `component_type` <=> 1 AND `sequence` <=> 3 AND `component_id` <=> 50173 AND `name` <=> CONVERT(0x4b6c61737372202d205265736561726368207468652043656e74617572204d616c616479 USING utf8mb4) AND `description` <=> '') OR (`achievement_id` <=> 500041000 AND `component_type` <=> 1 AND `sequence` <=> 4 AND `component_id` <=> 50174 AND `name` <=> CONVERT(0x4b6c61737372202d204375726520746865204d616c616479 USING utf8mb4) AND `description` <=> '') OR (`achievement_id` <=> 500041000 AND `component_type` <=> 3 AND `sequence` <=> 0 AND `component_id` <=> 2058 AND `name` <=> CONVERT(0x5265616368204c6576656c203530 USING utf8mb4) AND `description` <=> '') OR (`achievement_id` <=> 500041000 AND `component_type` <=> 3 AND `sequence` <=> 0 AND `component_id` <=> 7011 AND `name` <=> CONVERT(0x53657270656e74 USING utf8mb4) AND `description` <=> ''))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Centaur preimage conflict: achievement_components'; END IF;
IF (SELECT COUNT(*) FROM `items` WHERE id IN(53565,53566,53567)) <> 3 OR EXISTS(SELECT 1 FROM `items` WHERE (id IN(53565,53566,53567)) AND NOT((`id` <=> 53565 AND `name` <=> 'Fieldstrider Chain Belt' AND `icon` <=> 549 AND `classes` <=> 49629 AND `hp` <=> 50 AND `mana` <=> 45 AND `ac` <=> 11) OR (`id` <=> 53566 AND `name` <=> 'Fieldstrider Ceremonial Mantle' AND `icon` <=> 798 AND `classes` <=> 15906 AND `hp` <=> 45 AND `mana` <=> 50 AND `ac` <=> 8) OR (`id` <=> 53567 AND `name` <=> 'Fieldstrider Blanket' AND `icon` <=> 658 AND `classes` <=> 65535 AND `hp` <=> 50 AND `mana` <=> 45 AND `ac` <=> 13))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Centaur preimage conflict: items (reduced to NMS schema columns)'; END IF;
