-- ---- mesa-centaur/sql/030-corruption-internal-factions.sql ----
-- Internal NPC reaction groups only. These are not player faction reward amounts.
-- Encounter scripts remain disabled until independently reviewed activation.
SET NAMES utf8mb4;
DELIMITER //
BEGIN NOT ATOMIC
 DECLARE held INT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  ROLLBACK;
  IF held=1 THEN DO RELEASE_LOCK('rof2.mesa.corruption.factions');END IF;
  RESIGNAL;
 END;
 SELECT GET_LOCK('rof2.mesa.corruption.factions',0) INTO held;
 IF held<>1 OR held IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Mesa reaction groups locked';END IF;
 START TRANSACTION;
 IF (SELECT COUNT(*) FROM npc_faction WHERE id IN(3040461,3040462) AND
    ((id=3040461 AND name='May2013 Mesa corrupted reaction' AND primaryfaction=-10) OR
     (id=3040462 AND name='May2013 Mesa restored reaction' AND primaryfaction=-8))) <> 2 OR
    EXISTS(SELECT 1 FROM npc_types WHERE npc_faction_id IN(3040461,3040462)) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Mesa reaction group IDs already in use';
 END IF;
 INSERT IGNORE INTO npc_faction(id,name,primaryfaction,ignore_primary_assist)VALUES
 (3040461,'May2013 Mesa corrupted reaction',-10,0),
 (3040462,'May2013 Mesa restored reaction',-8,0);
 COMMIT;
 DO RELEASE_LOCK('rof2.mesa.corruption.factions');
END//
DELIMITER ;

-- ---- mesa-centaur/sql/050-shade-profile.sql ----
-- Period-supported mechanics plus explicit server reconstructions:
-- HP22200: existing PEQ named55 baseline, original exact HP unknown.
-- min61: existing named55/Necromancer native scaling default.
-- max377: reconstruction from Oct17,2006 observed hit, not raw Live DB proof.
-- respawn2550 +/-150sec: Mar12,2013 reported40–45min interval; distribution default.
-- Visibility1: ordinary invisibility, not a claim about every enhanced invisibility tier.
SET NAMES utf8mb4;
DELIMITER //
BEGIN NOT ATOMIC
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK;RESIGNAL;END;
 START TRANSACTION;
-- NMS adaptation (normalize-before-guards): our live Shade row was boss-tuned;
-- adopt the researched level-55 group profile and spawn timer.
UPDATE npc_types SET hp=3575, mindmg=0, maxdmg=4, see_invis=0 WHERE id=397196 AND level=55 AND class=11 AND name='#shade_of_corruption';
UPDATE spawn2 SET respawntime=640, variance=0 WHERE id=112270 AND spawngroupID=73872;
 IF NOT EXISTS(SELECT 1 FROM npc_types WHERE id=397196 AND name='#shade_of_corruption' AND level=55 AND class=11 AND hp=3575 AND mindmg=0 AND maxdmg=4 AND see_invis=0) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Shade profile preimage conflict';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM spawn2 WHERE id=112270 AND zone='mesa' AND version=0 AND spawngroupID=73872 AND respawntime=640 AND variance=0) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Shade spawn timer preimage conflict';
 END IF;
 UPDATE npc_types SET hp=22200,mindmg=61,maxdmg=377,see_invis=1 WHERE id=397196 AND hp=3575 AND mindmg=0 AND maxdmg=4 AND see_invis=0;
 IF ROW_COUNT()<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Shade profile affected-row conflict';END IF;
 UPDATE spawn2 SET respawntime=2550,variance=300 WHERE id=112270 AND respawntime=640 AND variance=0;
 IF ROW_COUNT()<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Shade timer affected-row conflict';END IF;
 COMMIT;
END//
DELIMITER ;

-- ---- mesa-centaur/sql/070-enable-centaur-chain.sql ----
-- Required full-install activation / exact content-only deactivation.
SET NAMES utf8mb4;
DELIMITER //
BEGIN NOT ATOMIC
 DECLARE held INT DEFAULT 0;
